@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Orbitron:wght@500;600;700;800&display=swap');
:root{color-scheme:dark;--cyan:#59f6ff;--purple:#ac70ff;--orange:#ff9d59;--ink:#070b18;--muted:#75819e}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);font-family:'DM Mono',monospace;color:#eaf7ff;touch-action:none}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#070b18;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.scanlines{position:absolute;inset:0;pointer-events:none;opacity:.14;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,rgba(170,205,255,.06) 4px);mix-blend-mode:screen;z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:82px;padding:20px 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(5,9,23,.82),transparent)}.brand{display:flex;gap:11px;align-items:center;font:700 14px Orbitron,sans-serif;letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(89,246,255,.65);color:var(--cyan);font-size:16px;transform:rotate(45deg);box-shadow:0 0 17px #42efff35}.brand-mark::first-letter{transform:rotate(-45deg)}.brand>span:last-child{line-height:1}.brand-dim{color:#7d8aa8}.brand small{display:block;color:#7a8aa8;font:9px 'DM Mono',monospace;letter-spacing:2px;margin-top:5px}.hud{display:flex;align-items:center;gap:28px}.crystal-count{font:700 21px Orbitron,sans-serif;display:flex;align-items:center;gap:8px;text-shadow:0 0 12px #61f5ff55}.crystal-count small{font:11px 'DM Mono',monospace;color:#7886a3;margin-left:-6px}.gem-icon{font-size:18px;color:var(--cyan);text-shadow:0 0 12px var(--cyan)}.hearts{display:flex;gap:7px}.hearts i{width:16px;height:16px;background:var(--orange);clip-path:path('M8 15 C6 13 0 9 0 5 C0 1 5 0 8 4 C11 0 16 1 16 5 C16 9 10 13 8 15Z');filter:drop-shadow(0 0 5px #ff8e59);transition:opacity .2s}.hearts i.empty{opacity:.18;filter:none}.pause-button{width:42px;height:42px;border:1px solid #71819d55;background:#10172b99;border-radius:12px;display:flex;justify-content:center;align-items:center;gap:5px;cursor:pointer}.pause-button span{width:3px;height:14px;border-radius:4px;background:#d7e6ff}.pause-button:hover{border-color:var(--cyan)}.level-label{position:absolute;z-index:2;top:95px;left:35px;font-size:10px;letter-spacing:1.6px;color:#8998b4}.level-label b{color:var(--cyan);padding:0 5px}.live-dot,.eyebrow span{display:inline-block;width:6px;height:6px;border-radius:50%;background:#61ffb0;box-shadow:0 0 9px #61ffb0;margin-right:8px;animation:blink 1.5s infinite}.progress-track{position:absolute;z-index:3;top:114px;left:35px;right:35px;height:2px;background:#e2edff18}.progress-track>div{height:100%;width:0;background:linear-gradient(90deg,var(--cyan),var(--purple));box-shadow:0 0 9px var(--cyan);transition:width .15s}.checkpoint-mark{position:absolute;left:51%;top:-4px;width:2px;height:10px;background:var(--orange);box-shadow:0 0 8px var(--orange)}.bottom-hint{position:absolute;z-index:2;bottom:19px;left:50%;transform:translateX(-50%);display:flex;gap:24px;color:#70809d;font-size:9px;letter-spacing:1px;white-space:nowrap}.bottom-hint b{color:#d7e6ff;margin-left:4px}.overlay{position:absolute;inset:0;z-index:6;display:grid;place-items:center;background:rgba(5,8,19,.58);backdrop-filter:blur(7px);transition:opacity .3s,visibility .3s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.panel{width:min(490px,calc(100vw - 32px));text-align:center;padding:35px 40px 28px;background:linear-gradient(145deg,rgba(17,24,46,.94),rgba(8,13,28,.96));border:1px solid #94b5ff24;border-radius:20px;box-shadow:0 25px 100px #0009,inset 0 1px #fff0;position:relative;overflow:hidden}.panel::before{content:'';position:absolute;top:0;left:18%;right:18%;height:1px;background:linear-gradient(90deg,transparent,var(--cyan),transparent);box-shadow:0 0 17px var(--cyan)}.eyebrow{font-size:9px;letter-spacing:2.4px;color:#91a2c2}.eyebrow span{width:5px;height:5px;margin:0 8px 1px}.eyebrow span:last-child{background:var(--purple);box-shadow:0 0 8px var(--purple)}.hero-icon{height:86px;display:grid;place-items:center;position:relative}.hero-gem{font-size:52px;color:var(--cyan);text-shadow:0 0 12px #55f6ff,0 0 40px #55f6ff99;animation:float 2.5s ease-in-out infinite}.hero-bot{position:absolute;width:37px;height:33px;left:calc(50% + 24px);top:29px;border:2px solid #bd89ff;background:#262149;clip-path:polygon(15% 0,85% 0,100% 30%,100% 100%,0 100%,0 30%);box-shadow:0 0 14px #b16dff}.hero-bot i{position:absolute;width:5px;height:5px;background:var(--cyan);top:12px;left:7px;box-shadow:13px 0 var(--cyan)}h1{font:800 clamp(32px,8vw,48px)/.98 Orbitron,sans-serif;letter-spacing:3px;margin:7px 0 17px;text-shadow:0 0 23px #9d67ff2b}h1 em{font-style:normal;color:var(--cyan);font-size:.77em;letter-spacing:6px}.panel>p{max-width:350px;margin:0 auto 20px;color:#9aa8c2;font-size:12px;line-height:1.8}.panel>p b{color:#f1f7ff;font-weight:500}.overlay-stats{display:flex;justify-content:center;gap:20px;padding:16px 0;border-top:1px solid #ffffff0f;border-bottom:1px solid #ffffff0f;color:#eaf7ff;font-size:10px}.overlay-stats span{display:flex;flex-direction:column;gap:5px}.overlay-stats small{font-size:8px;color:#7887a5;letter-spacing:1px}.primary-button{width:100%;margin-top:20px;height:50px;border:0;border-radius:8px;background:linear-gradient(100deg,#49e9ef,#8c8bff);color:#07101e;font:700 12px Orbitron,sans-serif;letter-spacing:1.6px;cursor:pointer;box-shadow:0 7px 25px #49e9ef30;transition:transform .15s,filter .15s}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.12)}.primary-button span{font-size:18px;margin-left:10px}.mobile-hint{font-size:8px!important;letter-spacing:1.2px;margin:15px 0 0!important;color:#6b7896!important}.mobile-controls{display:none;position:absolute;z-index:4;bottom:max(24px,env(safe-area-inset-bottom));left:0;right:0;padding:0 24px;align-items:end;justify-content:space-between;pointer-events:none}.joystick{width:118px;height:118px;position:relative;pointer-events:auto;touch-action:none}.joy-ring{position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle,#1e2949bb,#11182bb3);border:1px solid #a7c7ff40;box-shadow:inset 0 0 25px #8db4ff14}.joy-knob{position:absolute;width:55px;height:55px;border-radius:50%;left:31px;top:31px;background:linear-gradient(145deg,#7484a6,#374564);border:1px solid #d5e6ff66;box-shadow:0 4px 16px #0009;pointer-events:none}.action-buttons{display:flex;align-items:end;gap:15px;pointer-events:auto}.action{width:76px;height:76px;border-radius:50%;border:1px solid #75f9ff88;background:radial-gradient(circle at 35% 25%,#3b5870,#102033ed);color:#dffaff;box-shadow:0 0 22px #55f6ff2b,inset 0 0 15px #55f6ff25;touch-action:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0}.action span{font-size:29px;line-height:32px}.action small{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#9fdde5}.action.jump{width:88px;height:88px;border-color:#c49aff99;background:radial-gradient(circle at 35% 25%,#59427b,#201938ed);box-shadow:0 0 25px #a970ff35,inset 0 0 15px #a970ff28}.action.jump span{font-size:37px;line-height:38px;color:#e6cfff}.action:active{transform:scale(.94);filter:brightness(1.3)}.toast{position:absolute;z-index:3;top:144px;left:50%;transform:translate(-50%,-10px);opacity:0;color:var(--cyan);font:11px Orbitron,sans-serif;letter-spacing:2px;text-shadow:0 0 15px var(--cyan);transition:opacity .2s,transform .2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes blink{50%{opacity:.4}}@keyframes float{50%{transform:translateY(-7px)}}
@media (pointer:coarse),(max-width:760px){.mobile-controls{display:flex}.bottom-hint{display:none}.topbar{padding:15px 17px;height:70px}.brand{font-size:12px}.brand-mark{width:29px;height:29px}.hud{gap:15px}.crystal-count{font-size:18px}.crystal-count small{font-size:9px}.hearts{gap:5px}.hearts i{width:14px;height:14px}.pause-button{width:38px;height:38px}.level-label{top:79px;left:18px;font-size:9px}.progress-track{top:96px;left:18px;right:18px}.panel{padding:25px 24px 21px}.hero-icon{height:70px}.hero-gem{font-size:44px}.hero-bot{top:23px}.overlay-stats{gap:13px}.overlay-stats span{font-size:9px}.overlay-stats small{font-size:7px}.mobile-hint{margin-top:12px!important}.toast{top:119px}}
@media (max-height:520px) and (pointer:coarse){.mobile-controls{padding:0 20px;bottom:12px}.joystick{width:90px;height:90px}.joy-knob{left:23px;top:23px;width:44px;height:44px}.action{width:62px;height:62px}.action.jump{width:70px;height:70px}.panel{padding:15px 25px}.hero-icon{height:50px}.hero-gem{font-size:36px}.hero-bot{transform:scale(.8);top:11px}.panel>p{margin-bottom:10px}.overlay-stats{padding:10px}.primary-button{margin-top:12px;height:42px}}

