(() => {
'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d',{alpha:false});
const ui={count:document.getElementById('crystalCount'),hearts:document.getElementById('hearts'),progress:document.getElementById('progressFill'),overlay:document.getElementById('overlay'),title:document.getElementById('overlayTitle'),text:document.getElementById('overlayText'),stats:document.getElementById('overlayStats'),primary:document.getElementById('primaryButton'),pause:document.getElementById('pauseButton'),toast:document.getElementById('toast'),joystick:document.getElementById('joystick'),knob:document.getElementById('joyKnob'),jump:document.getElementById('jumpControl'),attack:document.getElementById('attackControl')};
let W=innerWidth,H=innerHeight,DPR=1,S=64,baseY=0,cameraX=0,last=0,shake=0,gameState='title',toastTimer=0,audio=null;
const keys={left:false,right:false,jump:false,attack:false};let player,platforms,crystals,enemies,shots,particles,hazards,checkpoint,checkpointReached,crystalCount,hearts,jumpQueued=false,attackQueued=false,gameTime=0;const END=166;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,1.7);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0);S=clamp(Math.min(W/14.3,H/8.4),39,78);baseY=H*(W<700?.78:.76)}addEventListener('resize',resize);resize();
function makeLevel(){
 const floors=[[0,18,0],[19.35,19.5,0],[39.2,17,.35],[56.7,18,0],[75,18,.55],[93.5,18,0],[112,18,.35],[130.5,18,0],[149,17,0]];
 platforms=floors.map((p,i)=>({x:p[0],y:p[2],w:p[1],h:.62,z:0,type:i===1||i===5?'collapse':'floor',active:true,triggered:false,timer:0,id:'g'+i}));
 const ledges=[[7,2.2,3.8],[13,3.55,3.2],[26,2,4.4],[32,3.2,3.5],[46,2.4,4],[52,4,3.5],[66,2.5,4.1],[71,4.2,3.3],[84,2.6,4.2],[89,4.25,3.4],[103,2.2,3.8],[108,4,3.4],[121,2.6,4],[127,4.35,3.2],[140,2.5,4],[146,4.2,3.5],[157,2.3,4]];
 ledges.forEach((v,i)=>platforms.push({x:v[0],y:v[1],w:v[2],h:.38,z:i%3===0?-.2:0,type:'ledge',active:true,triggered:false,timer:0,id:'l'+i}));
 platforms.push({x:36.4,y:2.8,w:3.2,h:.35,z:0,type:'moving',active:true,phase:0,originY:2.8,id:'m0'},{x:97.3,y:3,w:3.2,h:.35,z:0,type:'moving',active:true,phase:2,originY:3,id:'m1'});
 const points=[[3,1.7],[5.3,2],[8,3.55],[11.3,2],[14.5,4.9],[17.3,2],[22,1.8],[25.4,3.5],[28.7,1.9],[33,4.9],[36,1.8],[42,2],[45,3.9],[49,1.8],[53,5.4],[55,2],[60,1.8],[64,2],[68,4],[73,5.5],[77,2.3],[81,2],[86,4.2],[91,2],[96,2],[100,4.8],[105,2],[110,5.1],[115,2],[119,2],[124,4.1],[129,5.7],[134,2],[138,2],[143,4],[148,2],[153,2],[158,4.8],[162,2]];
 crystals=points.map((p,i)=>({x:p[0],y:p[1],z:-.15,got:false,phase:i*.7}));
 enemies=[{type:'walker',x:10,y:0,left:8,right:15,v:1.15,hp:1,alive:true},{type:'flyer',x:24,y:3.4,originY:3.4,phase:0,hp:1,alive:true},{type:'shooter',x:34,y:0,shot:2.5,hp:1,alive:true},{type:'walker',x:44,y:.35,left:40,right:53,v:1.45,hp:1,alive:true},{type:'flyer',x:61,y:3.3,originY:3.3,phase:2,hp:1,alive:true},{type:'shooter',x:69,y:0,shot:1.6,hp:1,alive:true},{type:'walker',x:79,y:.55,left:76,right:91,v:1.55,hp:1,alive:true},{type:'flyer',x:99,y:3.3,originY:3.3,phase:1,hp:1,alive:true},{type:'shooter',x:107,y:0,shot:2,hp:1,alive:true},{type:'walker',x:117,y:.35,left:113,right:128,v:1.7,hp:1,alive:true},{type:'flyer',x:136,y:3.4,originY:3.4,phase:3,hp:1,alive:true},{type:'shooter',x:145,y:0,shot:1.3,hp:1,alive:true},{type:'walker',x:155,y:0,left:150,right:162,v:1.8,hp:1,alive:true}];
 hazards=[{x:16.5,w:1.7,type:'spikes'},{x:37.5,w:1.6,type:'spikes'},{x:54.3,w:1.4,type:'spikes'},{x:72,w:1.5,type:'spikes'},{x:91,w:1.7,type:'spikes'},{x:109.6,w:1.4,type:'spikes'},{x:128,w:1.5,type:'spikes'},{x:147,w:1.6,type:'spikes'}];
 checkpoint=82;checkpointReached=false;
}
function reset(){makeLevel();player={x:2,y:0,vx:0,vy:0,w:.68,h:1.12,grounded:true,jumps:0,face:1,invuln:0,attackTime:0,attackCooldown:0,dead:false};shots=[];particles=[];crystalCount=0;hearts=3;gameTime=0;cameraX=0;shake=0;keys.left=keys.right=keys.jump=keys.attack=false;updateHud()}
function updateHud(){ui.count.textContent=String(crystalCount).padStart(2,'0');[...ui.hearts.children].forEach((h,i)=>h.classList.toggle('empty',i>=hearts));ui.hearts.setAttribute('aria-label',`${hearts} hearts`);ui.progress.style.width=`${Math.min(100,player?player.x/END*100:0)}%`}
function unlockAudio(){if(!audio){try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch(e){return}}if(audio.state==='suspended')audio.resume()}
function sound(kind){if(!audio)return;const now=audio.currentTime,osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);const tones={jump:[360,570,.11,'sine'],pickup:[620,1040,.14,'sine'],hit:[170,75,.22,'sawtooth'],pulse:[400,160,.12,'triangle'],win:[540,1000,.4,'sine'],stomp:[120,65,.1,'square']};const [a,b,d,w]=tones[kind]||tones.pickup;osc.type=w;osc.frequency.setValueAtTime(a,now);osc.frequency.exponentialRampToValueAtTime(Math.max(30,b),now+d);gain.gain.setValueAtTime(.07,now);gain.gain.exponentialRampToValueAtTime(.001,now+d);osc.start(now);osc.stop(now+d)}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=1.6}
function start(){unlockAudio();reset();gameState='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function showOverlay(mode){gameState=mode;ui.overlay.classList.remove('hidden');ui.stats.style.display=mode==='title'?'flex':'none';if(mode==='title'){ui.title.innerHTML='CRYSTAL<br><em>PROTOCOL</em>';ui.text.innerHTML='The grid is going dark. Collect <b>20 energy crystals</b>, outsmart the sentries, and reach the gate.';ui.primary.innerHTML='INITIALIZE RUN <span>↗</span>'}else if(mode==='paused'){ui.title.innerHTML='RUN<br><em>PAUSED</em>';ui.text.textContent='Take a breath, runner. The grid will wait.';ui.primary.innerHTML='RESUME RUN <span>↗</span>'}else if(mode==='win'){ui.title.innerHTML='GATE<br><em>OPEN</em>';ui.text.innerHTML=`Protocol complete. You secured <b>${crystalCount} crystals</b> and brought the grid back online.`;ui.primary.innerHTML='RUN AGAIN <span>↻</span>';sound('win')}else{ui.title.innerHTML='SIGNAL<br><em>LOST</em>';ui.text.innerHTML='The sentries reclaimed the sector. Your run ends here — the grid needs you.';ui.primary.innerHTML='RETRY SECTOR <span>↻</span>'}}
ui.primary.addEventListener('click',()=>gameState==='paused'?(gameState='playing',ui.overlay.classList.add('hidden'),last=performance.now(),requestAnimationFrame(loop)):start());ui.pause.addEventListener('click',()=>{if(gameState==='playing')showOverlay('paused');else if(gameState==='paused'){gameState='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}});
function setKey(e,on){const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','arrowdown'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')keys.left=on;if(k==='d'||k==='arrowright')keys.right=on;if(k===' '||k==='w'||k==='arrowup'){if(on&&!keys.jump)jumpQueued=true;keys.jump=on}if(k==='x'||k==='j'){if(on&&!keys.attack)attackQueued=true;keys.attack=on}if(on&&k==='escape'){if(gameState==='playing')showOverlay('paused');else if(gameState==='paused')ui.pause.click()}}
addEventListener('keydown',e=>setKey(e,true));addEventListener('keyup',e=>setKey(e,false));
function bindButton(el,key,queue){el.addEventListener('pointerdown',e=>{e.preventDefault();unlockAudio();el.setPointerCapture(e.pointerId);if(queue)jumpQueued=true;keys[key]=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,e=>{e.preventDefault();keys[key]=false})}bindButton(ui.jump,'jump',true);bindButton(ui.attack,'attack',true);
let joyId=null;ui.joystick.addEventListener('pointerdown',e=>{e.preventDefault();unlockAudio();joyId=e.pointerId;ui.joystick.setPointerCapture(joyId);moveJoy(e)});function moveJoy(e){const r=ui.joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.35,len=Math.hypot(dx,dy),fac=Math.min(1,max/(len||1));ui.knob.style.transform=`translate(${dx*fac}px,${dy*fac}px)`;keys.left=dx< -12;keys.right=dx>12}ui.joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyId)moveJoy(e)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])ui.joystick.addEventListener(ev,()=>{joyId=null;keys.left=keys.right=false;ui.knob.style.transform=''})

