function burst(x,y,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,z:rand(-.4,.4),vx:rand(-2.2,2.2),vy:rand(.4,3.8),life:rand(.35,.8),max:.8,size:rand(.035,.11),color})}
